#include <iostream>
#include <vector>
#include <queue>
#include <utility>
using namespace std;

int orangesRotting(vector<vector<int>> &grid){
    queue<pair<int, int>> q;
    int fresh = 0;
    int minutes = 0;
    for (int i = 0; i < grid.size(); i++) {
        for (int j = 0; j < grid[i].size(); j++) {
            if (grid[i][j] == 2) {
                q.push({i, j});
            }
            else if (grid[i][j] == 1) {
                fresh ++;
            }
        }
    }
    while (!q.empty() && fresh > 0) {
        int size = q.size();

        for (int i = 0; i < size; i++) {
            pair<int, int> curr = q.front();
            int r = curr.first;
            int c = curr.second;
            q.pop();

            if (r + 1 < grid.size() && grid[r+1][c] == 1) {
                grid[r+1][c] = 2;
                fresh--;
                q.push({r+1, c});
            }

            if (r - 1 >= 0 && grid[r-1][c] == 1) {
                grid[r-1][c] = 2;
                fresh--;
                q.push({r-1, c});
            }

            if (c + 1 < grid[0].size() && grid[r][c+1] == 1) {
                grid[r][c+1] = 2;
                fresh--;
                q.push({r, c+1});
            }

            if (c - 1 >= 0 && grid[r][c-1] == 1) {
                grid[r][c-1] = 2;
                fresh--;
                q.push({r, c-1});
            }
        }
        minutes++;
    }
    if (fresh > 0) {
        return -1;
    }
    return minutes;
}

int main(){
    //vector<vector<int>> grid = {{1,1,0}, {0,1,1}, {0,1,2}};
    vector<vector<int>> grid = {{1,1,0}, {0,1,1}, {0,1,2}};
    int res = orangesRotting(grid);
    cout << res << "\n";
    return 0;
}
